CONFIG_REL = "projects/sci-assistant/config/sci_assistant_config.yaml"
IO_REL = "projects/sci-assistant/knowledge/method_io.json"
CHAIN_REL = "projects/sci-assistant/knowledge/chains.json"
JOBS_REL = "projects/sci-assistant/knowledge/io_jobs"
KINDS = ("材料", "配方", "数据", "结构", "势函数", "器件", "表征结果", "计算资源")
IO_SCHEMA = """每个方法一条记录：
{
  "method_id": "<原样>",
  "produces": [{"artifact": "产出物名称（原文术语优先）", "kind": "材料|配方|数据|结构|势函数|器件|表征结果", "quote": "逐字原文"}],
  "requires": [{"artifact": "输入/前提名称", "kind": "同上", "quote": "逐字原文"}],
  "note": "可选：该卡里是否明示了先后顺序"
}
🔴 每条 artifact 都必须有 quote，且 quote 是该 source 卡正文的连续子串；没有依据就不写。"""

BAD_CARD_RE = re.compile(r"综述|[Mm]ini-?review|[Rr]eview|WeChat|公众号|微信")


# ---------------------------------------------------------------- 基础

def load_config(path=None):
    import yaml
    p = path or os.path.join(K.VAULT, CONFIG_REL)
    with open(p, "r", encoding="utf-8") as f:
        return yaml.safe_load(f) or {}


def methods_path(cfg=None):
    rel = ((cfg or {}).get("sci") or {}).get("methods_db") or \
        "projects/sci-assistant/knowledge/methods_db.json"
    return rel if os.path.isabs(rel) else os.path.join(K.VAULT, rel)


def load_methods(cfg=None):
    with open(methods_path(cfg), encoding="utf-8") as f:
        return json.load(f).get("methods") or []


def norm_ws(s):
    return re.sub(r"\s+", " ", str(s or "")).strip()


def card_body(card):
    p = os.path.join(K.VAULT, "wiki/sources", card + ".md")
    if not os.path.isfile(p):
        return None
    return norm_ws(K.read_text(p))


def bucket(kind):
    k = str(kind or "")
    if k == "配方":
        return "配方"
    if k in ("材料",):
        return "材料"
    if k in ("数据",):
        return "数据"
    if k in ("结构", "势函数"):
        return k
    if k == "表征结果":
        return "表征结果"
    return k


# ---------------------------------------------------------------- 计划

def select_methods(filter_terms, limit, methods=None):
    """按方法名/材料/来源卡是否含目标词挑方法；保证三类都有（合成/表征/测试/计算）。"""
    methods = methods if methods is not None else load_methods()
    terms = [t for t in re.split(r"[\s,，;；]+", filter_terms or "") if t]
    picked = []
    for m in methods:
        if m.get("category") not in ("合成", "表征", "测试", "计算"):
            continue
        if m.get("tier") != "source":      # 概念页是二手综合，不参与链（链要一手卡）
            continue
        text = " ".join([m.get("name_zh") or "", m.get("name_en") or "",
                         " ".join(str((x or {}).get("name") or "")
                                  for x in (m.get("materials") or []))])
        card = os.path.basename(m.get("page_path") or "").replace(".md", "")
        body = card_body(card) if card else None
        hay = text + " " + (body[:4000] if body else "")
        if terms and not any(t in hay for t in terms):
            continue
        if BAD_CARD_RE.search(card or ""):
            continue
        picked.append(m)
    picked.sort(key=lambda m: (m.get("category"), m.get("name_zh") or ""))
    # 按类别轮转取，避免 limit 截断后只剩「合成」一批（否则链的两端凑不齐）
    by_cat = {}
    for m in picked:
        by_cat.setdefault(m["category"], []).append(m)
    order = [c for c in ("计算", "合成", "表征", "测试") if by_cat.get(c)]
    out, i = [], 0
    while len(out) < int(limit) and any(by_cat.get(c) for c in order):
        c = order[i % len(order)]
        if by_cat.get(c):
            out.append(by_cat[c].pop(0))
        i += 1
    return out


def load_io(path=None):
    """读现有 method_io.json（不存在则空），用于 --skip-existing 与增量提取。"""
    p = path or os.path.join(K.VAULT, IO_REL)
    if not os.path.isfile(p):
        return {}
    with open(p, encoding="utf-8") as f:
        return json.load(f).get("methods") or {}


def plan_io(filter_terms=None, limit=24, batch_size=6, out_dir=None, methods=None,
            skip_existing=False, batch_start=1, manifest_name="manifest.json",
            known_ids=None):
    picked = select_methods(filter_terms, limit, methods)
    skipped = 0
    if skip_existing:
        done = known_ids if known_ids is not None else set(load_io())
        before = len(picked)
        picked = [m for m in picked if m.get("method_id") not in done]
        skipped = before - len(picked)
    batches = [picked[i:i + batch_size] for i in range(0, len(picked), batch_size)]
    out_dir = out_dir or os.path.join(K.VAULT, JOBS_REL)
    os.makedirs(out_dir, exist_ok=True)
    manifest = {
        "generated_at": datetime.date.today().isoformat(),
        "schema": IO_SCHEMA,
        "total": len(picked),
        "skipped_existing": skipped,
        "batch_size": batch_size,
        "batches": [{
            "batch_id": f"io_{int(batch_start) + i:02d}",
            "items": [{
                "method_id": m.get("method_id"),
                "name_zh": m.get("name_zh"),
                "category": m.get("category"),
                "card": os.path.basename(m.get("page_path") or "").replace(".md", ""),
            } for m in b],
        } for i, b in enumerate(batches)],
    }
    path = os.path.join(out_dir, manifest_name)
    with open(path, "w", encoding="utf-8", newline="\n") as f:
        f.write(json.dumps(manifest, ensure_ascii=False, indent=2) + "\n")
    return path, manifest


# ---------------------------------------------------------------- 合并 / 校验

def validate_io(rec, body_norm, known_ids):
    mid = (rec.get("method_id") or "").strip()
    if mid not in known_ids:
        return None, {"error": "unknown_method"}
    if body_norm is None:
        return None, {"error": "card_missing"}
    clean = {"method_id": mid, "produces": [], "requires": [],
             "note": (rec.get("note") or "").strip()}
    dropped = 0
    for key in ("produces", "requires"):
        for it in rec.get(key) or []:
            if not isinstance(it, dict):
                continue
            q = norm_ws(it.get("quote"))
            kind = str(it.get("kind") or "").strip()
            art = str(it.get("artifact") or "").strip()
            if not q or q not in body_norm or kind not in KINDS or not art:
                dropped += 1
                continue
            clean[key].append({"artifact": art, "kind": kind, "quote": q})
    if not clean["produces"] and not clean["requires"]:
        return None, {"error": "no_valid_items", "dropped": dropped}
    return clean, {"dropped": dropped}


def merge_io(merge_dir, methods=None, out_path=None):
    methods = methods if methods is not None else load_methods()
    known = {m.get("method_id") for m in methods}
    by_card = {os.path.basename(m.get("page_path") or "").replace(".md", ""): m
               for m in methods}
    manifest_p = os.path.join(merge_dir, "manifest.json")
    if not os.path.isfile(manifest_p):
        raise SystemExit(f"[!] 缺少 {manifest_p}")
    io = {}
    if os.path.isfile(out_path or ""):
        with open(out_path, encoding="utf-8") as f:
            io = json.load(f).get("methods") or {}
    accepted, rejected = [], []
    for fn in sorted(f for f in os.listdir(merge_dir)
                     if f.startswith("io_") and f.endswith(".json")):
        with open(os.path.join(merge_dir, fn), encoding="utf-8") as f:
            payload = json.load(f)
        recs = payload if isinstance(payload, list) else payload.get("records") or []
        for rec in recs:
            mid = (rec.get("method_id") or "").strip()
            m = next((x for x in methods if x.get("method_id") == mid), None)
            body = card_body(os.path.basename(m.get("page_path") or "").replace(".md", "")) if m else None
            clean, st = validate_io(rec, body, known)
            if not clean:
                rejected.append({"method_id": mid, "reason": st.get("error"),
                                 "batch": fn, "dropped": st.get("dropped", 0)})
                continue
            io[mid] = clean
            accepted.append(clean)
    doc = {"generated_at": datetime.date.today().isoformat(),
           "methods": io,
           "stats": {"accepted": len(accepted), "rejected": len(rejected),
                     "rejected_detail": rejected}}
    out_path = out_path or os.path.join(K.VAULT, IO_REL)
    os.makedirs(os.path.dirname(out_path), exist_ok=True)
    with open(out_path, "w", encoding="utf-8", newline="\n") as f:
        f.write(json.dumps(doc, ensure_ascii=False, indent=2) + "\n")
    with open(out_path, encoding="utf-8") as f:
        back = json.load(f)
    if len(back.get("methods") or {}) != len(io):
        raise SystemExit("[!] IO 写后复算失败")
    return doc, accepted, rejected


# ---------------------------------------------------------------- 建链

GENERIC_TERMS = {"电解液", "电解质", "溶剂", "共溶剂", "电池", "材料", "样品", "配方",
                 "数据", "结构", "结果", "性能", "实验", "体系", "基础", "候选", "溶液",
                 "电化学", "添加剂", "界面"}
ALLOWED_TRANSITIONS = {("计算", "合成"), ("计算", "测试"), ("合成", "表征"),
                       ("合成", "测试"), ("表征", "计算"), ("表征", "测试"),
                       ("测试", "计算")}


def _tokens(s):
    """英文/型号 token（≥3 字符）+ 中文 3-gram；后者用于避免「电解液」这类空壳词命中。"""
    s = norm_ws(s)
    out = set()
    for m in re.finditer(r"[A-Za-z][A-Za-z0-9\-]{2,}", s):
        out.add(m.group(0).lower())
    for run in re.findall(r"[\u4e00-\u9fff]{3,}", s):
        for i in range(len(run) - 2):
            out.add(run[i:i + 3])
    return out - GENERIC_TERMS


def term_overlap(a, b):
    """术语配对：共享一个**非空壳** token（型号/化学式/中文 3-gram）。"""
    return bool(_tokens(a) & _tokens(b))


def build_chains(io_doc=None, methods=None, include_typed=True, max_typed=24):
    """建链：先收「共享术语」的强边，再补「类别级」弱边（数量受限）。

    强边 = 产出物与输入物共享型号/化学式/中文 3-gram（specific）；
    弱边 = kind 相同但术语不同，只按「方法类别衔接」推出（typed），
    报告里必须与强边区分——它不保证同一材料体系。
    """
    methods = methods if methods is not None else load_methods()
    by_id = {m.get("method_id"): m for m in methods}
    io_doc = io_doc or {}
    io = io_doc.get("methods") or {}
    strong, weak = [], []
    for a_id, a in io.items():
        for b_id, b in io.items():
            if a_id == b_id:
                continue
            ma, mb = by_id.get(a_id), by_id.get(b_id)
            if not ma or not mb:
                continue
            pair = (ma.get("category"), mb.get("category"))
            same_card = (ma.get("page_path") == mb.get("page_path"))
            if not same_card and pair not in ALLOWED_TRANSITIONS:
                continue
            for p in a.get("produces") or []:
                for r in b.get("requires") or []:
                    if bucket(p["kind"]) != bucket(r["kind"]):
                        continue
                    common = {
                        "from": a_id, "to": b_id,
                        "from_name": ma.get("name_zh"), "to_name": mb.get("name_zh"),
                        "from_category": ma.get("category"),
                        "to_category": mb.get("category"),
                        "relation": "产出→输入",
                        "artifact": p["artifact"],
                        "matched_input": r["artifact"],
                        "kind": p["kind"],
                        "from_quote": p["quote"], "to_quote": r["quote"],
                        "source_card": os.path.basename(ma.get("page_path") or "").replace(".md", ""),
                        "same_card": same_card,
                    }
                    if term_overlap(p["artifact"], r["artifact"]):
                        strong.append(dict(common, evidence_level="term", confidence="medium"))
                    elif same_card:
                        weak.append(dict(common, evidence_level="same-card",
                                         confidence="medium"))
                    else:
                        weak.append(dict(common, evidence_level="category",
                                         confidence="low"))
    def _dedupe(items):
        seen, out = set(), []
        for e in sorted(items, key=lambda x: (not x["same_card"], x["from"], x["to"])):
            k = (e["from"], e["to"], bucket(e["kind"]))
            if k in seen:
                continue
            seen.add(k)
            out.append(e)
        return out

    def _balanced(items, max_n):
        """弱边按来源≤2、目标≤1 均衡挑选，避免某个方法（如 AHTech）占满列表。"""
        out, out_n, in_n = [], {}, {}
        for e in sorted(items, key=lambda x: (x["from"], x["to"])):
            if out_n.get(e["from"], 0) >= 2 or in_n.get(e["to"], 0) >= 1:
                continue
            out.append(e)
            out_n[e["from"]] = out_n.get(e["from"], 0) + 1
            in_n[e["to"]] = in_n.get(e["to"], 0) + 1
            if len(out) >= max_n:
                break
        return out

    uni_strong = _dedupe(strong)
    uni_weak = _balanced(_dedupe(weak), int(max_typed)) if include_typed else []
    uniq = uni_strong + uni_weak
    doc = {"generated_at": datetime.date.today().isoformat(),
           "methods_with_io": len(io),
           "edges": uniq,
           "stats": {"edges": len(uniq),
                     "term_edges": len(uni_strong),
                     "category_edges": sum(1 for e in uniq
                                           if e["evidence_level"] == "category"),
                     "same_card": sum(1 for e in uniq if e["same_card"]),
                     "by_kind": {k: sum(1 for e in uniq if bucket(e["kind"]) == k)
                                 for k in {bucket(e["kind"]) for e in uniq}}},
           "note": ("term 边=产出物与输入物共享型号/化学式/中文 3-gram；"
                    "category 边=只按方法类别与产物类型衔接（不保证同一材料体系），"
                    "均已逐条校验 quote；依赖关系是推断，不是作者明示的因果。")}
    return doc


# ---------------------------------------------------------------- 报告

def render_report(doc, methods=None):
    by_id = {m.get("method_id"): m for m in (methods or [])}
    L = ["# 方法链（产出 → 输入）", "",
         f"> 生成于 {datetime.date.today().isoformat()} ｜ 带 IO 的方法 {doc.get('methods_with_io')} 条"
         f" ｜ 边 {doc['stats']['edges']} 条（术语共享 {doc['stats'].get('term_edges', 0)}"
         f" / 类别级 {doc['stats'].get('category_edges', 0)}）",
         "> ⚠️ 依赖关系是**推断**，不是作者明示的因果或先后；每条边都附两侧原文引文，使用前请核对。",
         "> 「术语共享」边：产出物与输入物共享型号/化学式/中文词；"
         "「类别级」边：只按方法类别与产物类型衔接，**不保证同一材料体系**，跨论文使用时需自行适配。", ""]
    edges = doc.get("edges") or []
    if not edges:
        L.append("（没有可呈现的链：先跑 `--plan` / 子 agent 提取 / `--merge`）")
        return "\n".join(L) + "\n"
    L += ["## 链一览", "", "| # | 产出方法 | → | 输入方法 | 介质 | 证据类型 |",
          "|---|---|---|---|---|---|"]
    for i, e in enumerate(edges, 1):
        kind = {"term": "术语共享", "category": "类别级（弱）",
                "same-card": "同卡"}.get(e.get("evidence_level"), e.get("confidence"))
        L.append(f"| {i} | {e['from_name']}（{e['from_category']}） | → | "
                 f"{e['to_name']}（{e['to_category']}） | {e['artifact']} / {e['kind']} | "
                 f"{kind} |")
    L += ["", "## 逐条依据", ""]
    for i, e in enumerate(edges, 1):
        L.append(f"### {i}. {e['from_name']} → {e['to_name']}")
        L.append("")
        L.append(f"- 产出：**{e['artifact']}**（{e['kind']}）｜ 引文：{e['from_quote']}")
        L.append(f"- 输入：**{e['matched_input']}**（{e['kind']}）｜ 引文：{e['to_quote']}")
        L.append(f"- 来源卡：[[sources/{e['source_card']}]]"
                 + ("（同一张卡内）" if e["same_card"] else "（跨卡）"))
        L.append("")
    return "\n".join(L) + "\n"


# ---------------------------------------------------------------- 自检

def _selftest():
    fails = []

    def chk(label, cond, detail=""):
        print(("  ok   " if cond else "  FAIL ") + label +
              (f"   [{detail}]" if detail and not cond else ""))
        if not cond:
            fails.append(label)

    tmp = K.make_temp_dir(prefix="sci_chain_")
    try:
        body = norm_ws("先用水热法合成 LiFePO4 正极材料。随后用 XRD 表征其物相。")
        methods = [
            {"method_id": "source:A", "name_zh": "水热合成", "category": "合成",
             "page_path": "wiki/sources/A.md"},
            {"method_id": "source:B", "name_zh": "XRD 物相分析", "category": "表征",
             "page_path": "wiki/sources/B.md"},
        ]
        rec_a = {"method_id": "source:A",
                 "produces": [{"artifact": "正极材料", "kind": "材料",
                               "quote": "水热法合成 LiFePO4 正极材料"}],
                 "requires": [{"artifact": "前驱体", "kind": "材料",
                               "quote": "先用水热法合成"}], "note": ""}
        rec_b = {"method_id": "source:B",
                 "produces": [{"artifact": "物相结果", "kind": "表征结果",
                               "quote": "用 XRD 表征其物相"}],
                 "requires": [{"artifact": "正极材料", "kind": "材料",
                               "quote": "正极材料"}], "note": ""}
        clean, st = validate_io(rec_a, body, {"source:A", "source:B"})
        chk("校验：合法 quote 通过",
            clean is not None and len(clean["produces"]) == 1 and len(clean["requires"]) == 1,
            str(st))
        clean_b, _ = validate_io(rec_b, body, {"source:A", "source:B"})
        bad = dict(rec_a)
        bad["produces"] = [{"artifact": "电解液", "kind": "配方", "quote": "原文没有的电解液"}]
        bad["requires"] = []
        clean2, st2 = validate_io(bad, body, {"source:A", "source:B"})
        chk("校验：伪造 quote 被拒", clean2 is None and st2.get("dropped") == 1)
        chk("校验：未知 method_id 被拒",
            validate_io(dict(rec_a, method_id="source:Z"), body, {"source:A"})[0] is None)

        doc = build_chains({"methods": {"source:A": clean, "source:B": clean_b}},
                           methods=methods)
        edges = doc["edges"]
        chk("建链：材料产出 → 材料输入成边",
            any(e["from"] == "source:A" and e["to"] == "source:B" for e in edges),
            str([(e["from"], e["to"]) for e in edges]))
        chk("建链：同一对只保留一条（按 kind 去重）", len(edges) == 1, str(len(edges)))
        chk("建链：共享术语 -> evidence_level=term",
            edges and edges[0]["evidence_level"] == "term")

        md = render_report(doc, methods)
        chk("渲染：含引文与来源卡", "引文：" in md and "[[sources/" in md)
        chk("渲染：写明是推断、并区分术语共享/类别级",
            "推断" in md and "术语共享" in md and "类别级" in md)

        # 反例：kind 不同不成边
        rec_c = {"method_id": "source:A", "produces": [{"artifact": "电解液配方",
                                                        "kind": "配方",
                                                        "quote": "水热法合成 LiFePO4 正极材料"}],
                 "requires": [], "note": ""}
        doc2 = build_chains({"methods": {"source:A": rec_c, "source:B": clean}},
                            methods=methods)
        chk("建链：kind 不同不成边", doc2["stats"]["edges"] == 0)

        # 计划：增量提取（跳过已有 IO）、批次编号起点、清单另存
        # 反例保护：若不传 skip_existing，两个方法都会被排进计划
        mlist = [{"method_id": "source:A", "name_zh": "水热合成", "category": "合成",
                  "tier": "source", "page_path": "wiki/sources/A.md"},
                 {"method_id": "source:B", "name_zh": "XRD 物相分析", "category": "表征",
                  "tier": "source", "page_path": "wiki/sources/B.md"},
                 {"method_id": "source:C", "name_zh": "电化学测试", "category": "测试",
                  "tier": "source", "page_path": "wiki/sources/C.md"}]
        pdir = K.make_temp_dir(prefix="sci_plan_")
        try:
            _, man_full = plan_io(None, 10, 2, pdir, methods=mlist,
                                  manifest_name="m_full.json")
            chk("计划：不跳过时排入全部 3 个方法", man_full["total"] == 3,
                str(man_full["total"]))
            _, man_inc = plan_io(None, 10, 2, pdir, methods=mlist,
                                 skip_existing=True, known_ids={"source:A", "source:B"},
                                 batch_start=6, manifest_name="m_inc.json")
            chk("计划：--skip-existing 只留未提取的方法",
                man_inc["total"] == 1 and man_inc["skipped_existing"] == 2,
                f"{man_inc['total']}/{man_inc['skipped_existing']}")
            chk("计划：批次编号从 batch_start 起",
                [b["batch_id"] for b in man_inc["batches"]] == ["io_06"],
                str([b["batch_id"] for b in man_inc["batches"]]))
            chk("计划：清单另存后旧清单仍在",
                os.path.isfile(os.path.join(pdir, "m_full.json"))
                and os.path.isfile(os.path.join(pdir, "m_inc.json")))
        finally:
            K.remove_temp_dir(pdir)
    finally:
        K.remove_temp_dir(tmp)

    print(f"SELFTEST {'PASSED' if not fails else 'FAILED'}: {len(fails)} failure(s)")
    return 0 if not fails else 1


# ---------------------------------------------------------------- CLI

def main(argv=None):
    ap = argparse.ArgumentParser(description="方法链：产出 → 输入（N1）")
    ap.add_argument("--plan", action="store_true")
    ap.add_argument("--filter", default=None, help="目标词（空格分隔），按方法名/材料/卡片正文筛")
    ap.add_argument("--limit", type=int, default=24)
    ap.add_argument("--batch-size", type=int, default=6)
    ap.add_argument("--out-dir", default=None)
    ap.add_argument("--skip-existing", action="store_true",
                    help="跳过 method_io.json 里已有 IO 的方法（增量提取）")
    ap.add_argument("--batch-start", type=int, default=1,
                    help="批次编号起点（默认 1；增量提取时接在已有批次后面）")
    ap.add_argument("--manifest-name", default="manifest.json",
                    help="清单文件名（增量提取时另存，避免覆盖上一轮清单）")
    ap.add_argument("--merge", default=None, help="合并该目录下的 io_*.json")
    ap.add_argument("--build", action="store_true", help="由 method_io.json 建 chains.json")
    ap.add_argument("--report", default=None, help="输出目录（写 chains.md）")
    ap.add_argument("--json", action="store_true")
    ap.add_argument("--selftest", action="store_true")
    args = ap.parse_args(argv)

    if args.selftest:
        return _selftest()

    if args.plan:
        p, man = plan_io(args.filter, args.limit, args.batch_size, args.out_dir,
                         skip_existing=args.skip_existing,
                         batch_start=args.batch_start,
                         manifest_name=args.manifest_name)
        print(f"[ok] {man['total']} 个方法 → {len(man['batches'])} 批"
              + (f"（跳过已有 IO {man['skipped_existing']} 个）"
                 if man.get("skipped_existing") else ""))
        for b in man["batches"]:
            print(f"     {b['batch_id']}: " + "; ".join(
                f"{i['name_zh']}[{i['category']}]" for i in b["items"]))
        print(f"     清单: {os.path.relpath(p, K.VAULT)}")
        return 0

    if args.merge:
        d = args.merge if os.path.isabs(args.merge) else os.path.join(K.VAULT, args.merge)
        doc, acc, rej = merge_io(d)
        print(f"[ok] IO 合并：接受 {len(acc)}，拒绝 {len(rej)}；累计 {len(doc['methods'])} 个方法")
        for r in rej[:5]:
            print(f"     - {r['method_id']}: {r['reason']}")
        return 0

    if args.build:
        out = os.path.join(K.VAULT, IO_REL)
        io_doc = json.load(open(out, encoding="utf-8")) if os.path.isfile(out) else {}
        doc = build_chains(io_doc)
        p = os.path.join(K.VAULT, CHAIN_REL)
        with open(p, "w", encoding="utf-8", newline="\n") as f:
            f.write(json.dumps(doc, ensure_ascii=False, indent=2) + "\n")
        print(f"[ok] 链：{doc['stats']['edges']} 条（同卡 {doc['stats']['same_card']}）"
              f" ｜ 带 IO 方法 {doc['methods_with_io']}")
        print(f"     输出: {os.path.relpath(p, K.VAULT)}")
        if args.json:
            print(json.dumps(doc, ensure_ascii=False, indent=2))
        return 0

    if args.report:
        p = os.path.join(K.VAULT, CHAIN_REL)
        if not os.path.isfile(p):
            raise SystemExit("[!] 还没有 chains.json；先 --build")
        doc = json.load(open(p, encoding="utf-8"))
        out_dir = args.report if os.path.isabs(args.report) else os.path.join(K.VAULT, args.report)
        os.makedirs(out_dir, exist_ok=True)
        target = os.path.join(out_dir, "chains.md")
        text = render_report(doc, load_methods())
        with open(target, "w", encoding="utf-8", newline="\n") as f:
            f.write(text)
        print(f"[ok] 报告：{os.path.relpath(target, K.VAULT)}")
        return 0

    ap.print_help()
    return 1


if __name__ == "__main__":
    sys.exit(main())
